#include <bits/stdc++.h>
using namespace std;
const int INF = 0x7f7f7f7f;
int n,m,s,t,p,c,d,x[505],y[505];
int max_flow, min_cost;
int edge_count=1, head[5000005], next_edge[10000010], to_node[10000010], capacity[10000010], cost_edge[10000010];
int dist[5000005], parent[5000005], last_edge[5000005], flow_amount[5000005];
bool visited[5000005];

void addEdge(int u, int v, int cap, int cst) {
    next_edge[++edge_count] = head[u];
    to_node[edge_count] = v;
    capacity[edge_count] = cap;
    cost_edge[edge_count] = cst;
    head[u] = edge_count;
}

bool spfa() {
    memset(dist, 0x7f, sizeof(dist));
    memset(visited, false, sizeof(visited));
    queue<int> q;
    q.push(s);
    visited[s] = true;
    dist[s] = 0;
    flow_amount[s] = INT_MAX;
    parent[t] = -1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        visited[u] = false;
        for (int i = head[u]; i; i = next_edge[i]) {
            if (capacity[i] && dist[to_node[i]] > dist[u] + cost_edge[i]) {
                dist[to_node[i]] = dist[u] + cost_edge[i];
                parent[to_node[i]] = u;
                last_edge[to_node[i]] = i;
                flow_amount[to_node[i]] = min(flow_amount[u], capacity[i]);
                if (!visited[to_node[i]]) {
                    visited[to_node[i]] = true;
                    q.push(to_node[i]);
                }
            }
        }
    }
    return parent[t] != -1;
}

void run_mcmf() {
    max_flow = min_cost = 0;
    while (spfa()) {
        int current = t;
        max_flow += flow_amount[t];
        min_cost += flow_amount[t] * dist[t];
        while (current != s) {
            capacity[last_edge[current]] -= flow_amount[t];
            capacity[last_edge[current] ^ 1] += flow_amount[t];
            current = parent[current];
        }
    }
}

int node(int layer, int node_id) {
    return layer * n + node_id;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> p >> c >> d;
    s = 0;
    t = n * 99 + 1;
    for (int i=1, x; i<=p && cin>>x; i++) {
        addEdge(s, node(0,x), 1, 0);
        addEdge(node(0,x), s, 0, 0);
    }
    for (int i=1; i<=m; i++) {
        cin>>x[i]>>y[i];
    }
    for (int i=0; i<=99; i++) {
        addEdge(node(i,1), node(i+1,1), INF, 0);
        addEdge(node(i+1,1), node(i,1), 0, 0);
        for (int j=2; j<=n; j++) {
            addEdge(node(i,j), node(i+1,j), INF, c);
            addEdge(node(i+1,j), node(i,j), 0, -c);
        }
        for (int j=1; j<=m; j++) {
            for (int k=1; k<=p; k++) {
                int cst = d*k*k - d*(k-1)*(k-1) + c;
                addEdge(node(i,x[j]), node(i+1,y[j]), 1, cst);
                addEdge(node(i+1,y[j]), node(i,x[j]), 0, -cst);
                addEdge(node(i,y[j]), node(i+1,x[j]), 1, cst);
                addEdge(node(i+1,x[j]), node(i,y[j]), 0, -cst);
            }
        }
    }
    run_mcmf();
    cout << min_cost << "\n";
    return 0;
}
